// Whole-book shared q8 receiver: 20 strongest long groups fit; 167 long groups held.
// Exact GF(29) graph search; affine forbidden-hyperplane sieve on the final key coordinate.
#include <bits/stdc++.h>
using namespace std;
constexpr int N=29,Q=8,L=7; using U=uint32_t; using B=uint64_t; using V=array<uint8_t,Q>; using Key=array<int,Q>; using Perm=array<int,N>;
constexpr U ALL=(1u<<N)-1; constexpr B IMP=~B(0); const string SYM="0123456789abcdefghijklmnopqrs";
const vector<string> ALPHA={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int a){return (a%N+N)%N;} int val(char x){return int(SYM.find(x));} U rot(U x,int d){return d?((x<<d)|(x>>(N-d)))&ALL:x;}
int mul[N][N],sub[N][N],inv[N]; void init(){for(int i=0;i<N;i++)for(int j=0;j<N;j++){mul[i][j]=i*j%N;sub[i][j]=md(i-j);if(i*j%N==1)inv[i]=j;}}
V add(const V&a,const V&b){V c{};for(int i=0;i<Q;i++)c[i]=(a[i]+b[i])%N;return c;}
V diff(const V&a,const V&b){V c{};for(int i=0;i<Q;i++)c[i]=sub[a[i]][b[i]];return c;}
V unit(int j){V v{};v[j]=1;return v;}
struct Space{
 int d=7;array<V,Q>a{};array<uint8_t,Q>vars{};
 Space(){a[0][L]=1;for(int i=1;i<Q;i++){a[i][i-1]=1;vars[i-1]=i;}}
 V project(const V&v)const{V x{};for(int j=0;j<Q;j++)if(v[j]){for(int k=0;k<d;k++)x[k]=(x[k]+mul[v[j]][a[j][k]])%N;x[L]=(x[L]+mul[v[j]][a[j][L]])%N;}return x;}
 bool impose(const V&v){V eq=project(v);int p=d-1;while(p>=0&&!eq[p])p--;if(p<0)return !eq[L];int last=d-1,iv=inv[eq[p]];for(auto&r:a){int f=mul[r[p]][iv];if(f){for(int j=0;j<d;j++)if(j!=p)r[j]=sub[r[j]][mul[f][eq[j]]];r[L]=sub[r[L]][mul[f][eq[L]]];}if(p!=last)r[p]=r[last];r[last]=0;}vars[p]=vars[last];vars[last]=0;d--;return true;}
 bool primitive()const{for(int j=0;j<4;j++)if(a[j]!=a[j+4])return true;return false;}
 B code(const V&v)const{B x=0;for(int i=0;i<d;i++)x=x*N+v[i];return x*N+v[L];}
 B norm(const V&v)const{int j=0;while(j<d&&!v[j])j++;if(j==d)return v[L]?IMP:0;B x=1;int m=inv[v[j]];for(int i=0;i<d;i++)x=x*N+mul[v[i]][m];return x*N+mul[v[L]][m];}
 Key evaluate(const V&v)const{Key k{};for(int j=0;j<Q;j++){int x=a[j][L];for(int i=0;i<d;i++)x+=v[i]*a[j][i];k[j]=x%N;}return k;}
};
struct Edge{uint8_t c,p,j;}; struct Option{vector<Edge> e;string w;int start;};
struct Graph{
 array<uint8_t,N> r{},size{};array<V,N> off{};int comps=N;Space k;
 Graph(){for(int x=0;x<N;x++){r[x]=x;size[x]=1;}}
 int dim()const{return k.d+comps-1;}
 bool edge(Edge e){int c=e.c,p=e.p,j=e.j,rc=r[c],rp=r[p];V s=diff(add(off[p],unit(j)),off[c]);if(rc==rp)return k.impose(s);
  if(size[rc]<=size[rp]){for(int x=0;x<N;x++)if(r[x]==rc){r[x]=rp;off[x]=add(off[x],s);}size[rp]+=size[rc];size[rc]=0;}
  else{for(int x=0;x<N;x++)if(r[x]==rp){r[x]=rc;off[x]=diff(off[x],s);}size[rc]+=size[rp];size[rp]=0;}
  if(--comps==1){V sum{};for(auto&v:off)sum=add(sum,v);if(!k.impose(sum))return false;}return true;}
 bool valid()const{if(!k.primitive())return false;array<B,N>v{};for(int x=0;x<N;x++)v[x]=k.code(k.project(off[x]));for(int x=0;x<N;x++)for(int y=0;y<x;y++)if(r[x]==r[y]&&v[x]==v[y])return false;return true;}
 string sig()const{string s;s+=char(k.d);s.append((char*)k.vars.data(),Q);for(auto&a:k.a)s.append((char*)a.data(),Q);array<int,N>root;root.fill(-1);for(int x=0;x<N;x++){if(root[r[x]]<0)root[r[x]]=x;s+=char(root[r[x]]);auto v=k.project(diff(off[x],off[root[r[x]]]));s.append((char*)v.data(),Q);}return s;}
};
bool extend(const Graph&g,const Option&o,Graph&next){next=g;for(auto e:o.e)if(!next.edge(e))return false;return next.valid();}
struct Filter{
 const Graph&g;array<V,N>a{};unordered_set<B> forbidden;unordered_map<int,vector<B>> differences;array<int8_t,N*N*Q>cache;bool saturated=false;
 Filter(const Graph&x):g(x){cache.fill(-1);for(int i=0;i<N;i++)a[i]=g.k.project(g.off[i]);unordered_map<B,U>dirs;
  for(int i=0;i<N;i++)for(int j=0;j<i;j++)if(g.r[i]==g.r[j]){B z=g.k.norm(diff(a[i],a[j]));if(!z){saturated=true;return;}if(z==IMP)continue;forbidden.insert(z);auto&v=dirs[z/N];v|=1u<<(z%N);if(v==ALL){saturated=true;return;}}}
 bool allowed(Edge e){int c=e.c,p=e.p,j=e.j;auto&v=cache[(c*N+p)*Q+j];if(v>=0)return v;V shift=diff(add(a[p],g.k.a[j]),a[c]);int rc=g.r[c],rp=g.r[p];if(rc==rp){B z=g.k.norm(shift);return v=(z!=IMP&&!forbidden.count(z));}int id=rp*N+rc;auto it=differences.find(id);if(it==differences.end()){vector<B>f;for(int x=0;x<N;x++)if(g.r[x]==rp)for(int y=0;y<N;y++)if(g.r[y]==rc)f.push_back(g.k.code(diff(a[x],a[y])));sort(f.begin(),f.end());f.erase(unique(f.begin(),f.end()),f.end());it=differences.emplace(id,move(f)).first;}return v=!binary_search(it->second.begin(),it->second.end(),g.k.code(shift));}
 bool allowed(const Option&o){for(auto e:o.e)if(!allowed(e))return false;return true;}
};
vector<vector<string>> by(60);unordered_set<string>dict,oldDict;unordered_map<string,int>freq;
void addVariants(string word,int count){string s;for(size_t i=0;i<word.size();i++){char c=toupper(word[i]);if(c=='Q'&&i+1<word.size()&&toupper(word[i+1])=='U'){s+="CW";i++;continue;}if(c=='V')c='U';if(c=='K'||c=='Q')c='C';if(c=='Z')c='S';s+=c;}string w;function<void(size_t,bool)>rec=[&](size_t i,bool alias){if(i==s.size()){dict.insert(w);if(!alias)oldDict.insert(w);freq[w]=max(freq[w],count);return;}for(int n=1;n<=3&&i+n<=s.size();n++){string t=s.substr(i,n);int x=-1;if(n==3){if(t=="ING")x=21;}else if(t=="IO")x=27;else{auto p=find(ALPHA.begin(),ALPHA.end(),t);if(p!=ALPHA.end())x=int(p-ALPHA.begin());}if(x>=0){w+=SYM[x];rec(i+n,alias||t=="IO");w.pop_back();}}};rec(0,false);}
void dictionary(const string&path){ifstream f(path);if(!f)throw runtime_error("missing dict");string line;while(getline(f,line)){istringstream in(line);string w,n,extra;if(!(in>>w>>n)||in>>extra)continue;if(w.empty()||!all_of(w.begin(),w.end(),[](char c){return c>='a'&&c<='z';})||n.empty()||!all_of(n.begin(),n.end(),[](char c){return c>='0'&&c<='9';}))continue;addVariants(w,stoi(n));}if(dict.size()!=40730||oldDict.size()!=38910)throw runtime_error("base dict "+to_string(dict.size())+" old "+to_string(oldDict.size()));istringstream extras("akk1fr9f a9fgo4 7anf3j a9fg415gr9 d4ajif g3gai9g 0195gr9 i954qdgin p2i4sk h100i4f 5o49ok 3hf514o j3ha1f o9ok36 53o9 539f5r1f9iff a98ohagl hi8o1r4f 539f1jdgr9 hikia1i ni5idgr9 d4ifi41ogr9 d4ajokagq 57ifgr9 8of8if do4ohki g199ikl 5a451j0i4i95if");string w;while(extras>>w){dict.insert(w);oldDict.insert(w);}if(dict.size()!=40751||oldDict.size()!=38938)throw runtime_error("full dict");for(auto&w:dict)by[w.size()].push_back(w);for(auto&v:by)sort(v.begin(),v.end(),[](const string&a,const string&b){int x=freq[a],y=freq[b];return x==y?a<b:x>y;});}
