int A=167,SECOND=168; constexpr int HELD=167; const vector<int> ANCHORS={167,168,169,170,171}; vector<int> excluded; // 20 most restrictive original long groups, 167 independent long groups held.
using Maps=array<array<int,N>,Q>;
Maps maps(const Perm&pi,const Key&k){Perm ip{};for(int i=0;i<N;i++)ip[pi[i]]=i;Maps m{};for(int j=0;j<Q;j++)for(int c=0;c<N;c++)m[j][c]=ip[md(pi[c]-k[j])];return m;}
bool decode_rec(const string&c,const Maps&m,int i,int j,string&w,set<string>*out){if(i==(int)c.size()){if(!dict.count(w))return false;if(out)out->insert(w);return true;}int x=val(c[i]);bool yes=false;if(!x){w[i]='0';yes=decode_rec(c,m,i+1,j,w,out);if(yes&&!out)return true;}int p=m[j][x];if(p){w[i]=SYM[p];yes=decode_rec(c,m,i+1,(j+1)&7,w,out)||yes;}return yes;}
bool support(const string&c,const Maps&m){string w(c.size(),'0');for(int j=0;j<Q;j++)if(decode_rec(c,m,0,j,w,nullptr))return true;return false;}
set<string> decode(const string&c,const Maps&m){string w(c.size(),'0');set<string>out;for(int j=0;j<Q;j++)decode_rec(c,m,0,j,w,&out);return out;}
string encode(const string&w,const Perm&pi,const Key&k,int j){Perm ip{};for(int i=0;i<N;i++)ip[pi[i]]=i;string c;for(char a:w){int p=val(a);if(!p)c+='0';else{c+=SYM[ip[(pi[p]+k[j])%N]];j=(j+1)&7;}}return c;}
bool equalAction(const Perm&pi,const Key&k,const Perm&pj,const Key&l){auto a=maps(pi,k),b=maps(pj,l);for(int r=0;r<Q;r++){bool ok=true;for(int j=0;j<Q;j++)ok&=a[j]==b[(j+r)&7];if(ok)return true;}return false;}
struct Posting{int feature;vector<int>ids;vector<B>bits;};
struct Domain{string c;vector<Option>o;vector<vector<Posting>>post;vector<int>novel;};
Domain domain(const string&c,bool anchor){Domain d{c,{},{},{}};Graph base;unordered_set<string>seen;
 for(auto&w:by[c.size()]){int canonical=-1,cons=0;if(anchor)for(size_t i=0;i<w.size();i++){int p=val(w[i]),x=val(c[i]);if(!p)continue;if(p!=x){canonical=(Q-cons%Q)%Q;break;}cons++;}
  for(int start=0;start<Q;start++){if(canonical>=0&&start!=canonical)continue;Option o{{},w,start};int j=start;bool ok=true;for(size_t i=0;i<w.size();i++){int p=val(w[i]),x=val(c[i]);if(!p){if(x){ok=false;break;}continue;}if(j==0&&p==x){ok=false;break;}for(auto e:o.e)if(e.j==j&&(((e.c==x)!=(e.p==p))||((e.c==e.p)!=(x==p)))){ok=false;break;}if(!ok)break;o.e.push_back({uint8_t(x),uint8_t(p),uint8_t(j)});j=(j+1)&7;}if(!ok)continue;Graph t;if(!extend(base,o,t))continue;vector<int>codes;for(auto e:o.e)codes.push_back((e.c*N+e.p)*Q+e.j);sort(codes.begin(),codes.end());codes.erase(unique(codes.begin(),codes.end()),codes.end());string s((char*)codes.data(),codes.size()*sizeof(int));if(seen.insert(s).second)d.o.push_back(move(o));}}
 d.post.resize(c.size());vector<map<int,vector<int>>> tmp(c.size());for(int i=0;i<(int)d.o.size();i++){auto&o=d.o[i];if(!oldDict.count(o.w))d.novel.push_back(i);int j=o.start;for(int pos=0;pos<(int)c.size();pos++){int p=val(o.w[pos]);int f=p?1+j*N+p:0;if(p)j=(j+1)&7;tmp[pos][f].push_back(i);}}for(int pos=0;pos<(int)c.size();pos++)for(auto&[f,ids]:tmp[pos]){Posting a{f,move(ids),{}};if(a.ids.size()>=64){a.bits.assign((d.o.size()+63)/64,0);for(int id:a.ids)a.bits[id/64]|=B(1)<<(id&63);}d.post[pos].push_back(move(a));}return d;}
// If m distinct labels occupy a component, they are a subset of GF(29).
// For t=29-m missing labels, complete homogeneous h_{t+1} of the known offsets
// must vanish (coefficient of X^{t+1} in reciprocal of product(1-vX)).
// For m=29/28 use the square-moment equation; for m=27 use the cubic.
// Every legal permutation passes these equations; exact pack still verifies all labels.
array<U,N*N*N> quadRoots{};vector<U> cubicRoots(N*N*N*N);
void initRoots(){for(int a=0;a<N;a++)for(int b=0;b<N;b++)for(int c=0;c<N;c++){U mask=0;for(int x=0;x<N;x++)if(((a*x+b)*x+c)%N==0)mask|=1u<<x;quadRoots[(a*N+b)*N+c]=mask;}for(int a=0;a<N;a++)for(int b=0;b<N;b++)for(int c=0;c<N;c++)for(int d=0;d<N;d++){U mask=0;for(int x=0;x<N;x++)if((((a*x+b)*x+c)*x+d)%N==0)mask|=1u<<x;cubicRoots[((a*N+b)*N+c)*N+d]=mask;}}
int largestComponent(const Graph&g){return *max_element(g.size.begin(),g.size.end());}
// Return polynomial coefficients (constant first) in the final key coordinate,
// for a fixed prefix, before final exact disequality/packing checks.
array<int,4> momentPolynomial(const vector<V>&a,int d,const V&z){int m=a.size();array<int,2>S1{};array<int,3>S2{};array<int,4>S3{};for(auto&v:a){int b=v[L],y=v[d-1];for(int j=0;j<d-1;j++)b+=v[j]*z[j];b%=N;S1[0]+=b;S1[1]+=y;S2[0]+=b*b;S2[1]+=2*b*y;S2[2]+=y*y;if(m==27){S3[0]+=b*b*b;S3[1]+=3*b*b*y;S3[2]+=3*b*y*y;S3[3]+=y*y*y;}}for(int&v:S1)v%=N;for(int&v:S2)v%=N;for(int&v:S3)v%=N;array<int,4>out{};if(m==29){copy(S2.begin(),S2.end(),out.begin());return out;}if(m==28){out[0]=(S2[0]+S1[0]*S1[0])%N;out[1]=(S2[1]+2*S1[0]*S1[1])%N;out[2]=(S2[2]+S1[1]*S1[1])%N;return out;}for(int j=0;j<4;j++)out[j]=2*S3[j];for(int i=0;i<2;i++)for(int j=0;j<3;j++)out[i+j]+=3*S1[i]*S2[j];for(int i=0;i<2;i++)for(int j=0;j<2;j++)for(int k=0;k<2;k++)out[i+j+k]+=S1[i]*S1[j]*S1[k];for(int&v:out)v%=N;return out;}
U momentMask(const vector<V>&a,int d,const V&z){auto p=momentPolynomial(a,d,z);if(a.size()==27)return cubicRoots[((p[3]*N+p[2])*N+p[1])*N+p[0]];return quadRoots[(p[2]*N+p[1])*N+p[0]];}
struct Stats{uint64_t nodes=0,joins=0,keys=0,packed=0,sieves=0,sieveRejected=0,options=0,pairTest=0,novelTest=0,novelJoin=0,momentCalls=0,momentPrefixes=0,momentRoots=0;};
struct Search{
 vector<string>C;vector<Domain>D;vector<int>order;vector<Graph>seeds;vector<string>seedWords;int budget=3-int(excluded.size());chrono::steady_clock::time_point deadline;atomic<bool>found{false},timed{false};atomic<size_t>next{0},done{0};mutex lock;Perm answer{};Key answerK{};int answerOOV=-1;Stats all;
 Search(const vector<string>&c):C(c){for(int i=0;i<(int)c.size();i++)D.push_back(i<HELD?Domain{c[i],{},{},{}}:domain(c[i],i==A));for(int i=HELD;i<(int)c.size();i++)if(i!=A&&i!=SECOND&&find(excluded.begin(),excluded.end(),i)==excluded.end())order.push_back(i);sort(order.begin(),order.end(),[&](int a,int b){double x=log2(max<size_t>(1,D[a].o.size()))/C[a].size(),y=log2(max<size_t>(1,D[b].o.size()))/C[b].size();return x==y?a<b:x<y;});Graph base;unordered_set<string>seen;for(auto&o:D[A].o){Graph t;if(extend(base,o,t)&&seen.insert(t.sig()).second){seeds.push_back(t);seedWords.push_back(o.w);}}cout<<"ANCHOR "<<A<<" EXCLUDED";for(int i:excluded)cout<<" "<<i;cout<<" secondary="<<SECOND<<" options="<<D[A].o.size()<<" seeds="<<seeds.size()<<" secondaryOptions="<<D[SECOND].o.size()<<" train="<<order.size()+2<<" held="<<HELD<<endl;cout<<"DOMAINS";for(int g:order)cout<<" "<<g<<":"<<D[g].o.size()<<"/"<<D[g].novel.size();cout<<"\nNOVEL anchors "<<D[A].novel.size()<<"/"<<D[SECOND].novel.size()<<endl;}
 bool stop(){if(found||timed)return true;if(chrono::steady_clock::now()>=deadline){timed=true;return true;}return false;}
 void check(const Perm&pi,const Key&k,Stats&s){s.packed++;auto m=maps(pi,k);if(!support(C[A],m)||!support(C[SECOND],m))return;for(int i:excluded)if(support(C[i],m))return;int n=0;for(int i:order)if(!support(C[i],m)&&++n>budget)return;lock_guard<mutex>l(lock);if(!found){answer=pi;answerK=k;answerOOV=n+excluded.size();found=true;}}
 void pack(const Graph&g,const Key&k,Stats&s){s.keys++;bool primitive=false;for(int j=0;j<4;j++)primitive|=k[j]!=k[j+4];if(!primitive)return;array<int,N>v{},trans{};array<U,N>m{};for(int x=0;x<N;x++){int z=0;for(int j=0;j<Q;j++)z+=g.off[x][j]*k[j];v[x]=z%N;U b=1u<<v[x];if(m[g.r[x]]&b)return;m[g.r[x]]|=b;}int root=g.r[0];trans[root]=md(-v[0]);U used=rot(m[root],trans[root]);vector<int>rem;for(int x=0;x<N;x++)if(m[x]&&x!=root)rem.push_back(x);auto dfs=[&](auto&&self,U mask,vector<int>left)->void{if(stop())return;if(left.empty()){Perm pi{};for(int x=0;x<N;x++)pi[x]=(v[x]+trans[g.r[x]])%N;check(pi,k,s);return;}int pick=-1;U opts=0;for(int i=0;i<(int)left.size();i++){int r=left[i];U a=0;for(int t=0;t<N;t++)if(!(mask&rot(m[r],t)))a|=1u<<t;if(!a)return;if(pick<0||__builtin_popcount(a)<__builtin_popcount(opts)){pick=i;opts=a;if(__builtin_popcount(a)==1)break;}}int r=left[pick];left.erase(left.begin()+pick);while(opts){int t=__builtin_ctz(opts);opts&=opts-1;trans[r]=t;self(self,mask|rot(m[r],t),left);if(stop())return;}};dfs(dfs,used,rem);}
 // Every within-component pair imposes an affine disequality in the remaining key coordinates.
 // For a fixed prefix, a bit mask removes exactly the invalid final coordinates. Constant
 // violations discard a prefix. No sampling or heuristic score enters this enumeration.
 void sieve(const Graph&g,Stats&s){s.sieves++;vector<V>neq;unordered_set<B>seen;array<V,N>p{};for(int x=0;x<N;x++)p[x]=g.k.project(g.off[x]);for(int x=0;x<N;x++)for(int y=0;y<x;y++)if(g.r[x]==g.r[y]){V a=diff(p[x],p[y]);B id=g.k.norm(a);if(!id){s.sieveRejected++;return;}if(id!=IMP&&seen.insert(id).second)neq.push_back(a);}V z{};int d=g.k.d;if(!d){pack(g,g.k.evaluate(z),s);return;}int m=largestComponent(g);if(m>=27){s.momentCalls++;int root=int(max_element(g.size.begin(),g.size.end())-g.size.begin());vector<V>forms;for(int x=0;x<N;x++)if(g.r[x]==root)forms.push_back(p[x]);bool any=false;auto visit=[&](auto&&self,int i)->void{if(stop())return;if(i==d-1){s.momentPrefixes++;U good=momentMask(forms,d,z);s.momentRoots+=__builtin_popcount(good);while(good){int t=__builtin_ctz(good);good&=good-1;z[d-1]=t;bool ok=true;for(auto&a:neq){int v=a[L];for(int j=0;j<d;j++)v+=a[j]*z[j];if(v%N==0){ok=false;break;}}if(ok){any=true;pack(g,g.k.evaluate(z),s);}if(stop())return;}return;}for(int t=0;t<N;t++){z[i]=t;self(self,i+1);if(stop())return;}};visit(visit,0);if(!any&&!timed)s.sieveRejected++;return;}bool any=false;auto visit=[&](auto&&self,int i)->void{if(stop())return;if(i==d-1){U used=0;for(const V&a:neq){int t=a[L];for(int j=0;j<d-1;j++)t+=z[j]*a[j];t%=N;if(!a[d-1]){if(!t)return;}else{used|=1u<<mul[md(-t)][inv[a[d-1]]];if(used==ALL)return;}}U good=ALL^used;while(good){int t=__builtin_ctz(good);good&=good-1;z[d-1]=t;any=true;pack(g,g.k.evaluate(z),s);if(stop())return;}return;}for(int t=0;t<N;t++){z[i]=t;self(self,i+1);if(stop())return;}};visit(visit,0);if(!any&&!timed)s.sieveRejected++;}
 vector<int> live(int gid,Filter&f,size_t cap,Stats&s){vector<int>v;auto&d=D[gid];
  // At weakly constrained nodes, a clipped MRV scan is cheaper than building postings.
  if(f.g.dim()>19&&cap!=SIZE_MAX&&cap<512){for(int j=0;j<(int)d.o.size();j++){s.options++;if(f.allowed(d.o[j])){v.push_back(j);if(v.size()>=cap)break;}}return v;}
  struct Choice{size_t count=0;vector<const Posting*>p;};vector<Choice>choices;for(int pos=0;pos<(int)d.c.size();pos++){Choice a;for(auto&x:d.post[pos]){int id=x.feature;if(id&&!f.allowed({uint8_t(val(d.c[pos])),uint8_t((id-1)%N),uint8_t((id-1)/N)}))continue;a.count+=x.ids.size();a.p.push_back(&x);}if(!a.count)return {};choices.push_back(move(a));}sort(choices.begin(),choices.end(),[](auto&a,auto&b){return a.count<b.count;});auto test=[&](int id){s.options++;if(f.allowed(d.o[id]))v.push_back(id);return v.size()>=cap;};if(choices[0].count<=128||choices.size()==1){for(auto*p:choices[0].p)for(int id:p->ids)if(test(id))return v;sort(v.begin(),v.end());return v;}
  size_t n=(d.o.size()+63)/64;vector<B>bits(n),scratch(n);auto unite=[&](vector<B>&b,const Choice&a){for(auto*p:a.p){if(p->bits.empty()){for(int id:p->ids)b[id/64]|=B(1)<<(id&63);}else for(size_t k=0;k<n;k++)b[k]|=p->bits[k];}};unite(bits,choices[0]);for(size_t pos=1;pos<min<size_t>(3,choices.size());pos++){if(choices[pos].count==d.o.size())continue;fill(scratch.begin(),scratch.end(),0);unite(scratch,choices[pos]);bool any=false;for(size_t k=0;k<n;k++){bits[k]&=scratch[k];any|=bits[k]!=0;}if(!any)return {};}
  for(size_t k=0;k<n;k++){B b=bits[k];while(b){int j=__builtin_ctzll(b);b&=b-1;if(test(int(k*64+j)))return v;}}return v;}
 void dfs(const Graph&g,vector<int>rem,int b,Stats&s){if(stop())return;s.nodes++;if(g.dim()<=4||int(rem.size())<=b||(g.k.d<=2&&g.comps<=7)){sieve(g,s);return;}Filter f(g);if(f.saturated)return;int pick=-1;vector<int>best;size_t cap=SIZE_MAX;int ntry=min<int>(rem.size(),g.dim()>18?4:g.dim()>12?6:12);for(int i=0;i<ntry;){auto d=live(rem[i],f,cap,s);if(d.empty()){if(!b)return;b--;rem.erase(rem.begin()+i);ntry--;if(pick>i)pick--;continue;}if(pick<0||d.size()<cap){pick=i;best=move(d);cap=best.size();}i++;}if(pick<0){sieve(g,s);return;}int id=rem[pick];rem.erase(rem.begin()+pick);unordered_set<string>seen;vector<pair<int,Graph>>branches;for(int j:best){if(stop())return;s.joins++;Graph x;if(extend(g,D[id].o[j],x)&&seen.insert(x.sig()).second)branches.emplace_back(j,move(x));}stable_sort(branches.begin(),branches.end(),[&](auto&a,auto&b){int x=a.second.dim(),y=b.second.dim();if(x!=y)return x<y;return a.first<b.first;});for(auto&[j,x]:branches){if(stop())return;dfs(x,rem,b,s);}if(b)dfs(g,rem,b-1,s);}
 void run(int sec,int threads){deadline=chrono::steady_clock::now()+chrono::seconds(sec);vector<Stats>stats(threads);vector<thread>pool;for(int t=0;t<threads;t++)pool.emplace_back([&,t]{auto&s=stats[t];while(!stop()){size_t i=next.fetch_add(1);if(i>=seeds.size())break;const Graph&g=seeds[i];Filter f(g);if(!f.saturated){unordered_set<string>seen;vector<pair<int,Graph>>pairs;for(int j:live(SECOND,f,SIZE_MAX,s)){auto&o=D[SECOND].o[j];if(stop())break;s.pairTest++;Graph x;if(extend(g,o,x)&&seen.insert(x.sig()).second)pairs.emplace_back(j,move(x));}stable_sort(pairs.begin(),pairs.end(),[](auto&a,auto&b){int x=a.second.dim(),y=b.second.dim();if(x!=y)return x<y;return a.first<b.first;});for(auto&[j,x]:pairs){if(stop())break;dfs(x,order,budget,s);}}if(!found&&!timed){size_t d=++done;if(d%10==0){lock_guard<mutex>l(lock);cout<<"DONE "<<d<<"/"<<seeds.size()<<endl;}}}});for(auto&t:pool)t.join();for(auto&s:stats){all.nodes+=s.nodes;all.joins+=s.joins;all.keys+=s.keys;all.packed+=s.packed;all.sieves+=s.sieves;all.sieveRejected+=s.sieveRejected;all.options+=s.options;all.pairTest+=s.pairTest;all.novelTest+=s.novelTest;all.novelJoin+=s.novelJoin;all.momentCalls+=s.momentCalls;all.momentPrefixes+=s.momentPrefixes;all.momentRoots+=s.momentRoots;}cout<<"RESULT found="<<found<<" timed="<<timed<<" done="<<done<<"/"<<seeds.size()<<" nodes="<<all.nodes<<" joins="<<all.joins<<" keys="<<all.keys<<" packed="<<all.packed<<" sieves="<<all.sieves<<" rejected="<<all.sieveRejected<<" options="<<all.options<<" pairs="<<all.pairTest<<" novelTest="<<all.novelTest<<" novelJoin="<<all.novelJoin<<" momentCalls="<<all.momentCalls<<" momentPrefixes="<<all.momentPrefixes<<" momentRoots="<<all.momentRoots<<" OOV="<<answerOOV<<endl;if(found){cout<<"PI";for(auto x:answer)cout<<" "<<x;cout<<"\nKEY";for(auto x:answerK)cout<<" "<<x;cout<<endl;auto m=maps(answer,answerK);int n=0;for(int i=0;i<HELD;i++){auto w=decode(C[i],m);cout<<"HELD "<<i<<" "<<C[i]<<":";for(auto&x:w)cout<<" "<<x;cout<<endl;n+=!w.empty();}cout<<"HELD_SUPPORT "<<n<<"/"<<HELD<<endl;}};
};
struct Plant{vector<string>C,P;Perm pi;Key k;};
Plant plant(uint32_t seed){mt19937 rng(seed);Plant p;p.C=ORIGINAL;for(int i=0;i<N;i++)p.pi[i]=i;shuffle(p.pi.begin()+1,p.pi.end(),rng);do{for(int&k:p.k)k=rng()%N;}while(equal(p.k.begin(),p.k.begin()+4,p.k.begin()+4));auto m=maps(p.pi,p.k);for(int i=0;i<(int)ORIGINAL.size();i++){auto&v=by[ORIGINAL[i].size()];vector<double>w;for(auto&x:v)w.push_back(max(1,freq[x]));discrete_distribution<int>d(w.begin(),w.end());p.P.push_back(v[d(rng)]);bool oov=find(excluded.begin(),excluded.end(),i)!=excluded.end();if(oov){do{for(char&a:p.P.back())a=SYM[rng()%N];p.C[i]=encode(p.P[i],p.pi,p.k,rng()%Q);}while(support(p.C[i],m));}else p.C[i]=encode(p.P[i],p.pi,p.k,rng()%Q);}return p;}
int main(int argc,char**argv){if(argc!=7){cerr<<"usage: partition DICTIONARY SEED SECONDS THREADS FIRST SECOND; seed0 original\n";return 2;}init();initRoots();dictionary(argv[1]);int seed=stoi(argv[2]),sec=stoi(argv[3]),threads=stoi(argv[4]);A=stoi(argv[5]);SECOND=stoi(argv[6]);auto ia=find(ANCHORS.begin(),ANCHORS.end(),A),ib=find(ANCHORS.begin(),ANCHORS.end(),SECOND);if(ia==ANCHORS.end()||ib==ANCHORS.end()||ia>=ib)throw runtime_error("invalid ordered pair");for(auto it=ANCHORS.begin();it!=ib;it++)if(*it!=A)excluded.push_back(*it);if(ORIGINAL.size()!=187)throw runtime_error("profile");if(seed){auto p=plant(seed);cout<<"PLANT seed="<<seed<<" anchor="<<p.P[A]<<" carry="<<p.P[SECOND]<<"\n";Search s(p.C);{Graph base;int best=99,count=0;for(auto&o:s.D[A].o)if(o.w==p.P[A]){Graph g;if(!extend(base,o,g))continue;for(auto&q:s.D[SECOND].o)if(q.w==p.P[SECOND]){Graph t;if(extend(g,q,t)){count++;best=min(best,t.dim());}}}cout<<"TRUE_ANCHOR_PAIR_GRAPH feasible="<<count<<" minDimension="<<best<<endl;}s.run(sec,threads);if(s.found){auto m=maps(s.answer,s.answerK);int h=0;for(int i=0;i<HELD;i++)h+=decode(p.C[i],m).count(p.P[i]);cout<<"CONTROL action="<<equalAction(s.answer,s.answerK,p.pi,p.k)<<" heldtruth="<<h<<"/"<<HELD<<endl;return equalAction(s.answer,s.answerK,p.pi,p.k)&&h==HELD?0:1;}return 1;}Search s(ORIGINAL);s.run(sec,threads);return s.found?0:1;}
